/* tslint:disable */
/* eslint-disable */

export class Frame {
  private constructor();
  free(): void;
  [Symbol.dispose](): void;
  name: string;
}

export class MethodSample {
  private constructor();
  free(): void;
  [Symbol.dispose](): void;
  frames: Frame[];
}

/**
 * Converts the content of a JFR file to a Vec of stacktraces.
 *
 * The stacktraces are sorted by execution order.
 *
 * You can specify `include_native` to also record JNI or other calls to native methods.
 */
export function interpret_jfr(input: Uint8Array, include_native: boolean): MethodSample[];

export type InitInput = RequestInfo | URL | Response | BufferSource | WebAssembly.Module;

export interface InitOutput {
  readonly memory: WebAssembly.Memory;
  readonly __wbg_frame_free: (a: number, b: number) => void;
  readonly __wbg_get_frame_name: (a: number, b: number) => void;
  readonly __wbg_get_methodsample_frames: (a: number, b: number) => void;
  readonly __wbg_methodsample_free: (a: number, b: number) => void;
  readonly __wbg_set_frame_name: (a: number, b: number, c: number) => void;
  readonly __wbg_set_methodsample_frames: (a: number, b: number, c: number) => void;
  readonly interpret_jfr: (a: number, b: number, c: number, d: number) => void;
  readonly __wbindgen_add_to_stack_pointer: (a: number) => number;
  readonly __wbindgen_export: (a: number, b: number, c: number) => void;
  readonly __wbindgen_export2: (a: number, b: number) => number;
  readonly __wbindgen_export3: (a: number, b: number, c: number, d: number) => number;
}

export type SyncInitInput = BufferSource | WebAssembly.Module;

/**
* Instantiates the given `module`, which can either be bytes or
* a precompiled `WebAssembly.Module`.
*
* @param {{ module: SyncInitInput }} module - Passing `SyncInitInput` directly is deprecated.
*
* @returns {InitOutput}
*/
export function initSync(module: { module: SyncInitInput } | SyncInitInput): InitOutput;

/**
* If `module_or_path` is {RequestInfo} or {URL}, makes a request and
* for everything else, calls `WebAssembly.instantiate` directly.
*
* @param {{ module_or_path: InitInput | Promise<InitInput> }} module_or_path - Passing `InitInput` directly is deprecated.
*
* @returns {Promise<InitOutput>}
*/
export default function __wbg_init (module_or_path?: { module_or_path: InitInput | Promise<InitInput> } | InitInput | Promise<InitInput>): Promise<InitOutput>;
